    marker = max((x for x in counts if x != bg), key=lambda x: counts[x])
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, marker)]
    if not points:
        return [row[:] for row in grid]
    r0 = min(r for r, c in points); r1 = max(r for r, c in points)
    c0 = min(c for r, c in points); c1 = max(c for r, c in points)
    ar, ac = (r1-r0)//2, (c1-c0)//2
    stamp = [(r-r0, c-c0, grid[r][c]) for r, c in points]
